const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

module.exports = function(file, cb) {
  const dirname = path.dirname(file);
  const filename = path.basename(file);

  if (filename.indexOf('\0') !== -1) return cb(new Error('Invalid filename'));

  const cwd = path.resolve(dirname);
  if (!fs.existsSync(path.join(cwd, '.git'))) {
    return cb(new Error('Not a git repository'));
  }

  const child = spawn('git', ['blame', '--', filename], { cwd });

  let out = '';
  let err = '';
  child.stdout.on('data', chunk => out += chunk);
  child.stderr.on('data', chunk => err += chunk);

  child.on('error', e => cb(new Error(String(e))));
  child.on('close', code => {
    if (code !== 0) return cb(new Error(err || `git exited with ${code}`));
    const lines = out.split('\n');
    lines.unshift('');
    cb(null, lines);
  });
};
